import{_ as a,o as s,c as i,a2 as l}from"./chunks/framework.BbQrW5_t.js";const c=JSON.parse('{"title":"渗透方法论 PTES","description":"","frontmatter":{"title":"渗透方法论 PTES","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","中级"]},"headers":[],"relativePath":"study/cyber-security/chapters/中级篇/01-渗透方法论PTES.md","filePath":"study/cyber-security/chapters/中级篇/01-渗透方法论PTES.md","lastUpdated":1788493831000}'),e={name:"study/cyber-security/chapters/中级篇/01-渗透方法论PTES.md"};function n(o,t,d,h,r,p){return s(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="_01-·-渗透方法论-ptes——从-打点-到-交付报告" tabindex="-1">01 · 渗透方法论 PTES——从&quot;打点&quot;到&quot;交付报告&quot; <a class="header-anchor" href="#_01-·-渗透方法论-ptes——从-打点-到-交付报告" aria-label="Permalink to &quot;01 · 渗透方法论 PTES——从&quot;打点&quot;到&quot;交付报告&quot;&quot;">​</a></h1><blockquote><p>初级阶段你是&quot;知识点&quot;作战；PTES 给你<strong>工程化流程</strong>。它本质是一份交付质量标准：客户买的不是&quot;你黑进去了&quot;，而是&quot;系统性检查 + 可复现证据 + 可执行修复&quot;。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>说清七阶段各自的输入/动作/产出</li><li>用决策树从 nmap 结果选择攻击面</li><li>独立完成一台 VulnHub 靶机的完整报告</li><li>建立自己的渗透作业模板库</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_1-1-七阶段总览-输入→动作→产出" tabindex="-1">1.1 七阶段总览（输入→动作→产出） <a class="header-anchor" href="#_1-1-七阶段总览-输入→动作→产出" aria-label="Permalink to &quot;1.1 七阶段总览（输入→动作→产出）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>输入</th><th>核心动作</th><th>产出</th></tr></thead><tbody><tr><td>1 前期交互</td><td>客户需求</td><td>范围/授权/规则谈判</td><td><strong>授权书+测试范围单</strong></td></tr><tr><td>2 情报收集</td><td>范围单</td><td>域名/资产/人员/泄露信息</td><td>资产清单</td></tr><tr><td>3 威胁建模</td><td>资产清单</td><td>业务画像、高价值目标排序</td><td>攻击面优先级</td></tr><tr><td>4 漏洞分析</td><td>存活服务</td><td>扫描+手工验证+版本比对</td><td>漏洞列表</td></tr><tr><td>5 利用</td><td>验证过的漏洞</td><td>受控利用、拿权限</td><td>初始立足点</td></tr><tr><td>6 后渗透</td><td>立足点</td><td>提权/横向/取证/维持（范围内）</td><td>影响面证据</td></tr><tr><td>7 报告</td><td>全程记录</td><td>分级/复现/修复建议</td><td><strong>最终交付物</strong></td></tr></tbody></table><blockquote><p>红线提示：第 1 阶段的<strong>授权书</strong>是一切的合法性来源；无授权的&quot;渗透&quot;在刑法 285 条面前只是犯罪。</p></blockquote><h3 id="_1-2-扫描结果-→-攻击面决策树" tabindex="-1">1.2 扫描结果 → 攻击面决策树 <a class="header-anchor" href="#_1-2-扫描结果-→-攻击面决策树" aria-label="Permalink to &quot;1.2 扫描结果 → 攻击面决策树&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nmap -sS -sV 结果</span></span>
<span class="line"><span>├─ 22 ssh    → 版本漏洞? 弱口令(仅授权字典)? 密钥泄露?</span></span>
<span class="line"><span>├─ 80/443    → 指纹识别 → 目录爆破 → Web 漏洞族(初级篇 03 的反射)</span></span>
<span class="line"><span>├─ 445 smb   → 空会话? 共享枚举? 历史协议漏洞(版本比对)</span></span>
<span class="line"><span>├─ 3306/6379 → 弱口令? 未授权访问? (数据库暴露=直接进场)</span></span>
<span class="line"><span>└─ 其他端口  → 查 exploitdb/搜索引擎：&quot;中间件名+版本号 exploit&quot;</span></span></code></pre></div><p>决策核心：<strong>版本号 = CVE 的钥匙</strong>。<code>nginx 1.14 / OpenSSH 7.2</code> 这类信息直接决定攻击面清单——这就是为什么 <code>-sV</code> 永远要开。</p><h3 id="_1-3-靶机报告模板-vulnhub-实战用" tabindex="-1">1.3 靶机报告模板（VulnHub 实战用） <a class="header-anchor" href="#_1-3-靶机报告模板-vulnhub-实战用" aria-label="Permalink to &quot;1.3 靶机报告模板（VulnHub 实战用）&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 靶机渗透报告：Kioptrix Level 2</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 1. 目标与环境</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 2. 信息收集</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   nmap 结果 + 服务/版本表</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 3. 漏洞分析</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   每个候选漏洞：为什么怀疑/如何验证/验证结果</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 4. 利用过程（可复现）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   步骤化命令，每步附&quot;为什么&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 5. 后渗透</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   拿到的权限/能看到的资产/敏感信息</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 6. 修复建议（按漏洞逐条）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 7. 时间线与工具清单</span></span></code></pre></div><h3 id="_1-4-工程师加成" tabindex="-1">1.4 工程师加成 <a class="header-anchor" href="#_1-4-工程师加成" aria-label="Permalink to &quot;1.4 工程师加成&quot;">​</a></h3><ul><li>用 Git 管理&quot;每次作业&quot;：目录结构（recon/exploit/loot/report）+ 提交记录 = 完整证据链</li><li>把重复动作脚本化：信息收集流水线（第 1 年 W54 的 subfinder+httpx 就是起点）</li><li>报告用 Markdown 写 → pandoc 转 PDF，格式专业度碾压同行</li></ul><h2 id="🔬-动手实操" tabindex="-1">🔬 动手实操 <a class="header-anchor" href="#🔬-动手实操" aria-label="Permalink to &quot;🔬 动手实操&quot;">​</a></h2><p>对 Kioptrix Level 2 严格走七阶段，<strong>卡壳超过 30 分钟才允许看提示</strong>，且提示只看&quot;下一步该看什么&quot;而不是答案。</p><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li>拿到 shell 就兴奋收工——后渗透的影响面与报告才是价值</li><li>扫描一轮没思路就换靶机——枚举深度不足是新手通病（枚举 3 遍再放弃）</li><li>不写过程记录——复盘时证据链断裂，报告写不出</li><li>无授权打公网靶机之外的目标——红线</li><li>报告写成流水账——按&quot;风险分级+业务影响&quot;组织，客户语言</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. 为什么&quot;授权书&quot;是阶段 1 而不是形式？</summary><p>它定义了合法边界：目标 IP 段、允许的强度、时间窗、应急联系人。超出即违法；它同时保护测试方与被测方。</p></details><details><summary>2. nmap 发现 6379 开放（Redis），下一步优先验证什么？</summary><p>未授权访问：redis-cli 直连测试 CONFIG/INFO 权限——Redis 未授权是历史高频&quot;直接进场&quot;漏洞。</p></details><details><summary>3. 报告里&quot;影响面&quot;为什么比&quot;payload&quot;重要？</summary><p>客户决策依据是业务风险（哪些数据/系统受影响、被利用后果），payload 只是证据。</p></details><details><summary>4. 枚举为什么值得做三遍？</summary><p>不同工具覆盖不同面（端口/目录/用户/接口），且首轮认知会过滤掉&quot;当时没意识到重要&quot;的信息。</p></details><details><summary>5. 版本号信息如何转化为攻击面？</summary><p>&quot;软件名+版本&quot;检索已知 CVE/公开 exploit；同时评估利用条件（需认证?需要特定配置?）是否满足。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li><strong>W53-W56</strong>；资源：PTES 官网标准全文、《Metasploit 渗透测试指南》第 1-3 章</li></ul>`,27)])])}const k=a(e,[["render",n]]);export{c as __pageData,k as default};
